from AlgorithmImports import *


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_order_tag = "Strategy A"
        self.strategy_b_order_tag = "Strategy B"

    def OnData(self, data):
        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]

                if symbol == self.spy:
                    old_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
                    self.spy_sma.Update(bar.EndTime, bar.Close)

                    if self.previous_spy_close is not None:
                        if bar.Close < self.previous_spy_close:
                            pass

                    if old_spy_sma is not None:
                        self.previous_spy_sma = old_spy_sma

                    self.previous_spy_close = bar.Close

                elif symbol == self.aapl:
                    if self.previous_aapl_close is not None:
                        if bar.Close < self.previous_aapl_close:
                            self.aapl_red_streak += 1
                        else:
                            self.aapl_red_streak = 0

                    self.aapl_rsi.Update(bar.EndTime, bar.Close)
                    self.previous_aapl_close = bar.Close

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        current_spy_close = data.Bars[self.spy].Close
        current_spy_sma = self.spy_sma.Current.Value

        spy_crosses_below = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and current_spy_close > self.previous_spy_sma
        )

        spy_crosses_above = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and current_spy_close < self.previous_spy_sma
        )

        if self.strategy_a_lot > 0 and spy_crosses_above:
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag=self.strategy_a_order_tag
            )

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag=self.strategy_b_order_tag
            )

        if self.strategy_a_lot == 0 and spy_crosses_below:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue)
                / current_spy_close
            )

            if quantity > 0:
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag=self.strategy_a_order_tag
                )

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            current_aapl_close = data.Bars[self.aapl].Close

            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / current_aapl_close)

                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag=self.strategy_b_order_tag
                    )

        self.previous_spy_sma = current_spy_sma

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status != OrderStatus.Filled:
            return

        order = self.Transactions.GetOrderById(orderEvent.OrderId)
        fill_quantity = orderEvent.FillQuantity

        if order.Tag == self.strategy_a_order_tag:
            self.strategy_a_lot += fill_quantity
            self.strategy_a_lot = max(0, self.strategy_a_lot)

        elif order.Tag == self.strategy_b_order_tag:
            self.strategy_b_lot += fill_quantity
            self.strategy_b_lot = max(0, self.strategy_b_lot)
